import { JxChip, JxTagInput, useControllableState } from '@jinx-ui/react';

interface TagPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  placeholder?: string;
  ariaLabel?: string;
}

export default function TagPicker({
  value,
  defaultValue = [],
  onChange,
  placeholder = 'Введите тег и нажмите Enter',
  ariaLabel = 'Теги статьи',
}: TagPickerProps) {
  const [tags, setTags] = useControllableState<string[]>(value, defaultValue, onChange);

  const removeTagAt = (index: number) => {
    setTags(tags.filter((_, tagIndex) => tagIndex !== index));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 8px)' }}>
      <JxTagInput ariaLabel={ariaLabel} placeholder={placeholder} value={tags} onValueChange={setTags} />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-gap, 8px)' }}>
          {tags.map((tag, index) => (
            <JxChip key={`${tag}-${index}`} removable onRemove={() => removeTagAt(index)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

